import Image from "next/image";

const blur =
  "data:image/jpeg;base64,";

type PhotoProps = {
  src: string;
  alt: string;
  sizes: string;
  className?: string;
  priority?: boolean;
  fill?: boolean;
};

export function Photo({
  src,
  alt,
  sizes,
  className = "object-cover",
  priority = false,
  fill = true,
}: PhotoProps) {
  return (
    <Image
      src={src}
      alt={alt}
      fill={fill}
      sizes={sizes}
      priority={priority}
      placeholder="blur"
      blurDataURL={blur}
      className={className}
    />
  );
}
